package kr.blackwiki.smp;

import org.junit.jupiter.api.Test;
import java.math.BigInteger;
import static org.junit.jupiter.api.Assertions.*;

class ProgressRulesTest {
    @Test void rewardBoundariesAreExactForEveryLevel(){for(int level=1;level<=25;level++){assertEquals(0,ProgressRules.mobReward(level,false));assertEquals(0,ProgressRules.mobReward(level,true));}for(int level=26;level<50;level++){assertEquals(10,ProgressRules.mobReward(level,false));assertEquals(30,ProgressRules.mobReward(level,true));}assertEquals(35,ProgressRules.mobReward(50,false));assertEquals(75,ProgressRules.mobReward(50,true));assertThrows(IllegalArgumentException.class,()->ProgressRules.mobReward(51,false));}
    @Test void everyHigherMonsterLevelIsLessLikely(){double previous=2;for(int level=1;level<=50;level++){double weight=ProgressRules.weight(level,.94);assertTrue(weight>0&&weight<previous);previous=weight;}assertEquals(1,ProgressRules.mobLevel(0,.94));assertEquals(50,ProgressRules.mobLevel(Math.nextDown(1.0),.94));assertThrows(IllegalArgumentException.class,()->ProgressRules.mobLevel(1,.94));assertThrows(IllegalArgumentException.class,()->ProgressRules.weight(1,1));}
    @Test void distributionHasReasonableHighLevelTail(){double sum=0,tail=0;for(int i=1;i<=50;i++){double w=ProgressRules.weight(i,.94);sum+=w;if(i>=26)tail+=w;}double p50=ProgressRules.weight(50,.94)/sum;assertTrue(p50>.002&&p50<.004);assertTrue(tail/sum>.15&&tail/sum<.20);for(int i=0;i<10000;i++){int level=ProgressRules.mobLevel(i/10000.0,.94);assertTrue(level>=1&&level<=50);}}
    @Test void monsterHealthDoesNotDoubleAcrossLevelBoundary(){assertEquals(1,ProgressRules.healthFactor(1,.04),1e-10);assertEquals(2.96,ProgressRules.healthFactor(50,.04),1e-10);}
    @Test void miningThresholdsAndLevelBoundaries(){assertEquals(0,ProgressRules.threshold(1,100,50));assertEquals(100,ProgressRules.threshold(2,100,50));assertEquals(250,ProgressRules.threshold(3,100,50));assertEquals(1,ProgressRules.miningLevel(99,100,100,50));assertEquals(2,ProgressRules.miningLevel(100,100,100,50));assertEquals(2,ProgressRules.miningLevel(249,100,100,50));assertEquals(3,ProgressRules.miningLevel(250,100,100,50));assertEquals(100,ProgressRules.miningLevel(Long.MAX_VALUE,100,100,50));}
    @Test void multipleLevelRewardsCountEachNewLevelOnce(){int before=ProgressRules.miningLevel(99,100,100,50),after=ProgressRules.miningLevel(450,100,100,50);assertEquals(90,(after-before)*30);assertEquals(0,(after-after)*30);}
    @Test void theftRoundsDownWithoutOverflow(){assertEquals(0,ProgressRules.stolen(6));assertEquals(1,ProgressRules.stolen(7));assertEquals(149,ProgressRules.stolen(999));assertEquals(1500,ProgressRules.stolen(10001));long expected=BigInteger.valueOf(Long.MAX_VALUE).multiply(BigInteger.valueOf(15)).divide(BigInteger.valueOf(100)).longValueExact();assertEquals(expected,ProgressRules.stolen(Long.MAX_VALUE));}
    @Test void magicPricesAndStatsMatchRequest(){assertEquals(299900,MagicSwordItems.Kind.ORIUS.price);assertEquals(11.5,MagicSwordItems.Kind.ORIUS.damage);assertEquals(1.65,MagicSwordItems.Kind.ORIUS.speed);assertEquals(.05,MagicSwordItems.Kind.ORIUS.movement);assertEquals(2,MagicSwordItems.Kind.ORIUS.unbreaking);assertEquals(799900,MagicSwordItems.Kind.DEMON.price);assertEquals(13,MagicSwordItems.Kind.DEMON.damage);assertEquals(1.5,MagicSwordItems.Kind.DEMON.speed);assertEquals(.06,MagicSwordItems.Kind.DEMON.movement);assertEquals(3,MagicSwordItems.Kind.DEMON.unbreaking);assertEquals(1499900,MagicSwordItems.Kind.ANGEL.price);assertEquals(14,MagicSwordItems.Kind.ANGEL.damage);assertEquals(1.7,MagicSwordItems.Kind.ANGEL.speed);assertEquals(.03,MagicSwordItems.Kind.ANGEL.movement);assertEquals(3,MagicSwordItems.Kind.ANGEL.unbreaking);for(var kind:MagicSwordItems.Kind.values()){var p=ShopCatalogue.find(kind.id);assertEquals(kind.price,p.buy());assertTrue(p.magic());assertThrows(IllegalArgumentException.class,()->p.total(false,2));assertThrows(IllegalArgumentException.class,()->p.total(true,1));}}
}
